export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();
  private readonly ajv = new Ajv({
    allErrors: true,
    format: false,
    strictDefaults: false,
    strictKeywords: false,
  });
  private readonly dynamicValidators = new WeakMap<Record<string, unknown>, ValidateFunction>();

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  private compileSchema(toolName: string, inputSchema: Record<string, unknown>): ValidateFunction {
    const cached = this.dynamicValidators.get(inputSchema);
    if (cached) return cached;
    try {
      const compiled = this.ajv.compile(inputSchema);
      this.dynamicValidators.set(inputSchema, compiled);
      return compiled;
    } catch (error) {
      const reason = error instanceof Error ? error.message : String(error);
      throw new Error(`Invalid inputSchema for tool "${toolName}": ${reason}`);
    }
  }

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
    const validateInput =
      typeof definition === 'function' ? undefined : this.compileSchema(resolved.name, resolved.inputSchema);
    this.tools.set(resolved.name, {definitionSource: definition, execute, validateInput});
  }
